-- Minimal copy of the verified participant-table column types; fixture data only.
create role anon;create role authenticated;create role service_role bypassrls;
create schema auth;create schema officehub_private;grant usage on schema public,auth to anon,authenticated,service_role;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create function auth.role() returns text language sql stable as $$select current_setting('request.jwt.claim.role',true)$$;
create function auth.email() returns text language sql stable as $$select current_setting('request.jwt.claim.email',true)$$;
create table public.profiles(id uuid primary key,name text,email text,role text,department text,organisation text,avatar text,app_metadata jsonb default '{}');
create function public.officehub_department_key(dept text,org text) returns text language sql immutable as $$select case when org in ('HO','HOP','WEC','MEDEWELL') and lower(btrim(dept)) in ('top management','management') then 'management' when org='HO' and lower(btrim(dept)) in ('marketing and projects','projects and marketing','projects and mkt') then 'projects and marketing' else lower(btrim(dept)) end$$;
grant select on public.profiles to authenticated;
create table public.tasks("id" text primary key,"title" text,"description" text,"status" text,"priority" text,"department" text,"organisation" text,"assigned_to_id" uuid,"assigned_to_name" text,"assigned_to_avatar" text,"assigned_to_ids" text[],"created_by_id" uuid,"created_by_name" text,"due_date" text,"project_id" text,"sharepoint_doc_id" text,"pending_rating" boolean,"rating" jsonb,"completed_at" text,"cancelled_at" text,"created_at" timestamptz default now(),"assignment_type" text,"assigned_departments" text[],"assigned_organisations" text[]);
alter table public.tasks enable row level security;
grant all on public.tasks to anon,authenticated,service_role;
create policy fixture_old_broad_access on public.tasks for all using(true) with check(true);
create table public.meetings("id" text primary key,"title" text,"department" text,"date" text,"time" text,"start_time" text,"end_time" text,"duration_minutes" integer,"description" text,"organizer_id" uuid,"organizer_name" text,"agenda" text[],"meeting_type" text,"teams_join_url" text,"teams_meeting_id" text,"teams_passcode" text,"minutes" text,"status" text,"recurrence" text,"chair_id" uuid,"chair_name" text,"chair_email" text,"created_at" timestamptz default now());
alter table public.meetings enable row level security;
grant all on public.meetings to anon,authenticated,service_role;
create policy fixture_old_broad_access on public.meetings for all using(true) with check(true);
create table public.approvals("id" text primary key,"title" text,"description" text,"type" text,"amount" numeric,"department" text,"requested_by_id" uuid,"requested_by_name" text,"requested_date" text,"status" text,"approved_by" text,"approved_date" text,"notes" text,"urgency" text,"approver_ids" text[]);
alter table public.approvals enable row level security;
grant all on public.approvals to anon,authenticated,service_role;
create policy fixture_old_broad_access on public.approvals for all using(true) with check(true);
create table public.audit_log("id" text primary key,"actor_id" uuid,"actor_name" text,"actor_email" text,"event_type" text,"target_name" text,"timestamp" text,"badge_color" text);
alter table public.audit_log enable row level security;
grant all on public.audit_log to anon,authenticated,service_role;
create policy fixture_old_broad_access on public.audit_log for all using(true) with check(true);
create table public.task_ratings("id" text primary key,"task_id" text,"rated_user_id" uuid,"rated_by_id" uuid,"rating" integer,"comment" text,"rated_at" text);
alter table public.task_ratings enable row level security;
grant all on public.task_ratings to anon,authenticated,service_role;
create policy fixture_old_broad_access on public.task_ratings for all using(true) with check(true);
create table public.notifications("id" text primary key,"title" text,"message" text,"type" text,"meeting_id" text,"target_user_id" text,"created_at" text,"read" boolean,"actor_id" uuid,"actor_name" text,"actor_avatar" text,"priority" text,"pushed_to_microsoft_teams" boolean,"email_triggered" boolean,"email_recipients" text[],"email_sent_at" text,"email_subject" text,"metadata" jsonb);
alter table public.notifications enable row level security;
grant all on public.notifications to anon,authenticated,service_role;
create policy fixture_old_broad_access on public.notifications for all using(true) with check(true);
create table public.task_subtasks("id" text primary key,"task_id" text,"title" text,"completed" boolean);
alter table public.task_subtasks enable row level security;
grant all on public.task_subtasks to anon,authenticated,service_role;
create policy fixture_old_broad_access on public.task_subtasks for all using(true) with check(true);
create table public.task_assignees("task_id" text,"user_id" uuid,primary key(task_id,user_id));
alter table public.task_assignees enable row level security;
grant all on public.task_assignees to anon,authenticated,service_role;
create policy fixture_old_broad_access on public.task_assignees for all using(true) with check(true);
create table public.dispatched_emails("id" text primary key,"notification_id" text,"recipient_email" text,"recipient_name" text,"subject" text,"body_html" text,"body_text" text,"sent_at" text,"status" text);
alter table public.dispatched_emails enable row level security;
grant all on public.dispatched_emails to anon,authenticated,service_role;
create policy fixture_old_broad_access on public.dispatched_emails for all using(true) with check(true);
create table public.meeting_attendees("meeting_id" text,"user_id" uuid,"name" text,"email" text,"status" text,"avatar" text,"proposed_date" text,"proposed_time" text,"proposed_end_time" text,"proposal_note" text,"note" text,"comment" text,"responded_at" text,primary key(meeting_id,user_id));
alter table public.meeting_attendees enable row level security;
grant all on public.meeting_attendees to anon,authenticated,service_role;
create policy fixture_old_broad_access on public.meeting_attendees for all using(true) with check(true);
alter table public.task_ratings add foreign key(task_id) references public.tasks(id) on delete cascade;
alter table public.task_subtasks add foreign key(task_id) references public.tasks(id) on delete cascade;
alter table public.task_assignees add foreign key(task_id) references public.tasks(id) on delete cascade;
alter table public.meeting_attendees add foreign key(meeting_id) references public.meetings(id) on delete cascade;
